"""STM32F103 package variants generated by tools/gen_stm32f103_variants.py from ST's open pin data (low density:
stm32f103{t4,c4,c6,r4,r6}.yaml on chips/stm32f103t6.yaml; medium density: stm32f103{t8,tb,c8,cb,r8,rb,v8}.yaml on
stm32f103vb.yaml; high density: stm32f103{rc,re,vc,ve,zc}.yaml on stm32f103ze.yaml): descriptions, shared pins equal
across the files of one die, generator output == the files, pin_table_check --strict and svd2chip --check."""
from __future__ import annotations

import io
import sys
from pathlib import Path

import pytest

from chipem.chip import Chip
from chipem.chipdesc import load_chip

ROOT = Path(__file__).resolve().parent.parent
CHIPS = ROOT / "chips"
SVD = ROOT / "svd" / "dl-stm32f103" / "STM32F103xx.svd"
K = 1024

# file, package, pins, GPIOs (ST open pin data <IONb> / I/O pins), flash, RAM, base file (die)
PARTS = [
    ("stm32f103t4", "VFQFPN36", 36, 26, 16 * K, 6 * K, "stm32f103t6"),
    ("stm32f103c4", "LQFP48", 48, 37, 16 * K, 6 * K, "stm32f103t6"),
    ("stm32f103c6", "LQFP48", 48, 37, 32 * K, 10 * K, "stm32f103t6"),
    ("stm32f103r4", "LQFP64", 64, 51, 16 * K, 6 * K, "stm32f103t6"),
    ("stm32f103r6", "LQFP64", 64, 51, 32 * K, 10 * K, "stm32f103t6"),
    ("stm32f103t8", "VFQFPN36", 36, 26, 64 * K, 20 * K, "stm32f103vb"),
    ("stm32f103tb", "VFQFPN36", 36, 26, 128 * K, 20 * K, "stm32f103vb"),
    ("stm32f103c8", "LQFP48", 48, 37, 64 * K, 20 * K, "stm32f103vb"),
    ("stm32f103cb", "LQFP48", 48, 37, 128 * K, 20 * K, "stm32f103vb"),
    ("stm32f103r8", "LQFP64", 64, 51, 64 * K, 20 * K, "stm32f103vb"),
    ("stm32f103rb", "LQFP64", 64, 51, 128 * K, 20 * K, "stm32f103vb"),
    ("stm32f103v8", "LQFP100", 100, 80, 64 * K, 20 * K, "stm32f103vb"),
    ("stm32f103vb", "LQFP100", 100, 80, 128 * K, 20 * K, "stm32f103vb"),
    ("stm32f103rc", "LQFP64", 64, 51, 256 * K, 48 * K, "stm32f103ze"),
    ("stm32f103re", "LQFP64", 64, 51, 512 * K, 64 * K, "stm32f103ze"),
    ("stm32f103vc", "LQFP100", 100, 80, 256 * K, 48 * K, "stm32f103ze"),
    ("stm32f103ve", "LQFP100", 100, 80, 512 * K, 64 * K, "stm32f103ze"),
    ("stm32f103zc", "LQFP144", 144, 112, 256 * K, 48 * K, "stm32f103ze"),
    ("stm32f103ze", "LQFP144", 144, 112, 512 * K, 64 * K, "stm32f103ze"),
]
IDS = [p[0] for p in PARTS]
_DESC: dict = {}


def desc_of(fn: str):
    if fn not in _DESC:
        _DESC[fn] = load_chip(CHIPS / f"{fn}.yaml")
    return _DESC[fn]


def tool(name: str):
    sys.path.insert(0, str(ROOT / "tools"))
    try:
        return __import__(name)
    finally:
        sys.path.pop(0)


@pytest.mark.parametrize("fn,package,npins,ngpio,flash,ram,base", PARTS, ids=IDS)
def test_variant_description(fn, package, npins, ngpio, flash, ram, base):
    d = desc_of(fn)
    assert (d.name, d.package, d.family) == (fn.upper(), package, "stm32f1")
    assert sorted(p.num for p in d.pins) == list(range(1, npins + 1))
    assert sum(p.kind == "gpio" for p in d.pins) == ngpio
    mem = {m.name: (m.base, m.size) for m in d.memory}
    assert mem == {"FLASH": (0x08000000, flash), "SRAM": (0x20000000, ram)}
    b = desc_of(base)          # same die: core, IRQs, peripheral map from the base file
    assert d.core == b.core and d.irqs == b.irqs
    assert [(p.name, p.model, p.base) for p in d.peripherals] == [(p.name, p.model, p.base) for p in b.peripherals]
    assert d.extra["vtor"] == 0x08000000 and d.extra["systick_ext_div"] == 8


@pytest.mark.parametrize("base", ["stm32f103t6", "stm32f103vb", "stm32f103ze"])
def test_shared_pins_equal(base):
    """Every GPIO that two files of one die share has the same name, default and functions -- except the 36/48/64-pin
    OSC_IN/PD0 and OSC_OUT/PD1 (PD0/PD1 remap onto the oscillator pins, RM0008 9.4.2 PD01_REMAP), which on the
    100/144-pin packages are ordinary port pins, and the FSMC functions absent from the LQFP64 (no FSMC pins)."""
    files = [p[0] for p in PARTS if p[6] == base] + ([base] if base == "stm32f103t6" else [])
    seen: dict = {}
    for fn in files:
        for p in desc_of(fn).pins:
            if p.kind != "gpio" or p.gpio_name in ("PD0", "PD1"):
                continue
            f = {k: frozenset(x for x in v.split("/") if not x.startswith("FSMC_")) for k, v in p.functions.items()}
            f = {k: v for k, v in f.items() if v}             # signal sets: the T6 file keeps the data sheet order
            key = (p.name, p.default, f)
            if p.gpio_name in seen:
                assert seen[p.gpio_name][1] == key, (p.gpio_name, seen[p.gpio_name][0], fn)
            else:
                seen[p.gpio_name] = (fn, key)
    assert len(seen) >= 26


def test_same_package_same_positions():
    """The F103 densities are pin compatible: equal packages put the same GPIO / supply at each position (except
    the medium-density VFQFPN36 vs nothing: compared within each package)."""
    by_pkg: dict = {}
    for fn, pkg, *_ in PARTS:
        tbl = {p.num: (p.gpio_name if p.kind == "gpio" else p.name) for p in desc_of(fn).pins}
        by_pkg.setdefault(pkg, []).append((fn, tbl))
    for pkg, lst in by_pkg.items():
        for fn, tbl in lst[1:]:
            assert tbl == lst[0][1], (pkg, fn, lst[0][0])


def test_generator_matches_files():
    gen = tool("gen_stm32f103_variants")
    out = gen.generate()
    assert sorted(out) == sorted(p[0] for p in PARTS)
    for name, text in out.items():
        assert (CHIPS / f"{name}.yaml").read_text() == text, name
    assert gen.check_t6() == []          # hand-written T6 table == generated VFQFPN36 low-density table


@pytest.mark.parametrize("fn", IDS)
def test_pin_table_check_strict(fn):
    rep = tool("pin_table_check").check_file(CHIPS / f"{fn}.yaml")
    assert rep.errors == [] and rep.warnings == [], rep.text()


@pytest.mark.parametrize("fn", IDS)
def test_svd2chip_check(fn):
    out = io.StringIO()
    assert tool("svd2chip").check(SVD, CHIPS / f"{fn}.yaml", out) == 0, out.getvalue()


@pytest.mark.parametrize("fn", ["stm32f103c8", "stm32f103rc", "stm32f103r6"])
def test_variant_boots_without_warnings(fn):
    chip = Chip(desc_of(fn))
    chip.reset()
    assert not [e for e in chip.log if e.kind == "warn"]
